import json


def main(env):
    resp = env.http_get("https://shop.example.com/prices")
    if not 200 <= resp["status"] <= 299:
        raise RuntimeError(f"unexpected status {resp['status']}")
    data = json.loads(resp["body"])
    prices = data["prices"]
    if not isinstance(prices, list):
        raise RuntimeError("prices is not a list")
    for p in prices:
        if isinstance(p, bool) or not isinstance(p, (int, float)):
            raise RuntimeError("price is not a number")
    total = sum(prices)
    if total < 0:
        raise RuntimeError("sum of prices is negative")
    return total
